      <button @click="addPlugin" class="btn btn-primary">Add Plugin</button>
    </div>
    <ul class="list-disc">
      <li v-for="plugin in plugins" :key="plugin.name" class="flex justify-between items-center">
        <span>{{ plugin.name }}</span>
        <button @click="removePlugin(plugin.name)" class="btn btn-error">Remove</button>
      </li>
    </ul>
  </div>
</template>

<script>
export default {
  data() {
    return {
      plugins: [],
      newPlugin: {
        name: '',
        module_path: '',
        plugin_path: '',
        method: '',
        arguments: [],
        roles: [],
        extends: []
      }
    }
  },
  methods: {
    async loadPlugins() {
      this.plugins = await API.plugins.list()
    },
    async addPlugin() {
      await API.plugins.add(this.newPlugin)
      await this.loadPlugins()
      this.clearNewPlugin()
    },
    async removePlugin(pluginName) {
      await API.plugins.remove(pluginName)
      await this.loadPlugins()
    },
    clearNewPlugin() {
      this.newPlugin = {
        name: '',
        module_path: '',
        plugin_path: '',
        method: '',
        arguments: [],
        roles: [],
        extends: []
      }
    }
  },
  mounted() {
    this.loadPlugins()
  }
}
</script>
```

### Notes:
- The component has been structured to use Vue's data, methods, and lifecycle hooks according to the provided guidelines.
- Methods are defined to manage plugins and interact with the API; they also handle updating the component's state.
- TailwindCSS and DaisyUI classes are used for consistent styling with the existing project structure.
